Form.Module:
// =====================================================================
// ВНЕШНЯЯ ОБРАБОТКА: Отчёт розничных продаж из Vetais для 1С
// Требует: PostgreSQL ODBC Driver (psqlODBC) на компьютере с 1С
// Скачать: https://www.postgresql.org/ftp/odbc/versions/msi/
// Параметры подключения сохраняются автоматически между запусками.
// =====================================================================

#Область ОбработчикиСобытийФормы

&НаСоздании
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)
        Хост         = ХранилищеОбщихНастроек.Загрузить("ОтчетВетаис", "Хост",         "localhost");
        Порт         = ХранилищеОбщихНастроек.Загрузить("ОтчетВетаис", "Порт",         "5432");
        База         = ХранилищеОбщихНастроек.Загрузить("ОтчетВетаис", "База",         "vetais_probiko_local");
        Пользователь = ХранилищеОбщихНастроек.Загрузить("ОтчетВетаис", "Пользователь", "postgres");
        Пароль       = ХранилищеОбщихНастроек.Загрузить("ОтчетВетаис", "Пароль",       "");
        Организация  = ПервыйЭлементСправочника("Организации");
        СтавкаНДС   = Перечисления.СтавкиНДС.БезНДС;
        ДатаС        = НачалоМесяца(ДобавитьМесяц(ТекущаяДата(), -1));
        ДатаПо       = КонецМесяца(ДобавитьМесяц(ТекущаяДата(), -1));
КонецПроцедуры

&НаСервере
Функция ПервыйЭлементСправочника(ИмяСправочника)
        Выборка = Справочники[ИмяСправочника].Выбрать();
        Если Выборка.Следующий() Тогда
                Возврат Выборка.Ссылка;
        КонецЕсли;
        Возврат Справочники[ИмяСправочника].ПустаяСсылка();
КонецФункции

&НаСервере
Процедура СохранитьПараметрыПодключения()
        ХранилищеОбщихНастроек.Сохранить("ОтчетВетаис", "Хост",         Хост);
        ХранилищеОбщихНастроек.Сохранить("ОтчетВетаис", "Порт",         Порт);
        ХранилищеОбщихНастроек.Сохранить("ОтчетВетаис", "База",         База);
        ХранилищеОбщихНастроек.Сохранить("ОтчетВетаис", "Пользователь", Пользователь);
        ХранилищеОбщихНастроек.Сохранить("ОтчетВетаис", "Пароль",       Пароль);
КонецПроцедуры

#КонецОбласти

#Область ОбработчикиКомандФормы

&НаКлиенте
Процедура СформироватьОтчет(Команда)
        Если ПустаяСтрока(Хост) Или ПустаяСтрока(База) Тогда
                Сообщить("Заполните параметры подключения к PostgreSQL!", СтатусСообщения.Важное);
                Возврат;
        КонецЕсли;
        Если Не ЗначениеЗаполнено(ДатаС) Или Не ЗначениеЗаполнено(ДатаПо) Тогда
                Сообщить("Укажите период!", СтатусСообщения.Важное);
                Возврат;
        КонецЕсли;
        Если Не ЗначениеЗаполнено(Организация) Тогда
                Сообщить("Укажите организацию!", СтатусСообщения.Важное);
                Возврат;
        КонецЕсли;
        Если Не ЗначениеЗаполнено(НоменклатураУслуги)
                И Не ЗначениеЗаполнено(НоменклатураТовары) Тогда
                Сообщить("Укажите номенклатуру для услуг и/или товаров!", СтатусСообщения.Важное);
                Возврат;
        КонецЕсли;
        РезультатОтчета = "Запрос к Vetais...";
        Результат = СоздатьОтчетОРозничныхПродажах(
                Хост, ?(ПустаяСтрока(Порт), "5432", Порт),
                База, ?(ПустаяСтрока(Пользователь), "postgres", Пользователь), Пароль,
                ДатаС, КонецДня(ДатаПо),
                Организация, Склад,
                НоменклатураУслуги, НоменклатураТовары, СтавкаНДС);
        РезультатОтчета = Результат.Сообщение;
        Если Результат.Успех Тогда
                СохранитьПараметрыПодключения();
                ПоказатьЗначение(, Результат.ДокументСсылка);
        КонецЕсли;
КонецПроцедуры

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаСервереБезКонтекста
Функция ПолучитьДанныеИзВетаис(Хост, Порт, База, Пользователь, Пароль, ДатаОт, ДатаДо)
        СтрокаПодключения =
                "Driver={PostgreSQL ANSI(x64)};"
                + "Server=" + Хост + ";Port=" + Порт + ";Database=" + База + ";"
                + "Uid=" + Пользователь + ";Pwd=" + Пароль + ";"
                + "UseServerSidePrepare=0;Sslmode=disable;";
        ДатаОтФорм = Формат(ДатаОт, "ДФ=yyyy-MM-dd");
        ДатаДоФорм = Формат(ДатаДо, "ДФ=yyyy-MM-dd");
        ТекстЗапроса =
                "WITH totals AS ("
                + " SELECT sum(ai.sum_with_vat) FILTER (WHERE it.id_type=1) AS tovary,"
                + "   sum(ai.sum_with_vat) FILTER (WHERE it.id_type=2) AS uslugi,"
                + "   sum(ai.sum_with_vat) AS itogo"
                + " FROM accounts_items ai"
                + " JOIN accounts_headers ah ON ah.id=ai.account_header_id"
                + " LEFT JOIN items_type it ON it.id=ai.item_type_id"
                + " WHERE ai.deleted=0 AND ah.deleted=0"
                + "   AND ah.datetime_create::date BETWEEN '" + ДатаОтФорм + "' AND '" + ДатаДоФорм + "'"
                + ") SELECT round(coalesce(itogo,0)::numeric,2) AS itogo,"
                + " round(coalesce(uslugi,0)::numeric,2) AS uslugi,"
                + " round(coalesce(tovary,0)::numeric,2) AS tovary FROM totals";
        Результат = Новый Структура("Успех,Итого,Услуги,Товары,Ошибка", Ложь, 0, 0, 0, "");
        Попытка
                Соединение = Новый COMОбъект("ADODB.Connection");
                Соединение.ConnectionString = СтрокаПодключения;
                Соединение.CursorLocation   = 3;
                Соединение.Open();
                Команда = Новый COMОбъект("ADODB.Command");
                Команда.ActiveConnection = Соединение;
                Команда.CommandText      = ТекстЗапроса;
                Команда.CommandTimeout   = 60;
                РезАДО = Команда.Execute();
                Если Не РезАДО.EOF Тогда
                        Результат.Итого  = РезАДО.Fields.Item("itogo").Value;
                        Результат.Услуги = РезАДО.Fields.Item("uslugi").Value;
                        Результат.Товары = РезАДО.Fields.Item("tovary").Value;
                        Результат.Успех  = Истина;
                КонецЕсли;
                РезАДО.Close();
                Соединение.Close();
        Исключение
                Результат.Ошибка =
                        "ОШИБКА ПОДКЛЮЧЕНИЯ К VETAIS:" + Символы.ПС + ОписаниеОшибки() + Символы.ПС + Символы.ПС +
                        "Проверьте:" + Символы.ПС +
                        "1) Установлен ли psqlODBC: https://www.postgresql.org/ftp/odbc/versions/msi/" + Символы.ПС +
                        "2) Доступен ли порт " + Порт + " на сервере " + Хост;
        КонецПопытки;
        Возврат Результат;
КонецФункции

&НаСервереБезКонтекста
Функция СоздатьОтчетОРозничныхПродажах(
        Хост, Порт, База, Пользователь, Пароль,
        ДатаОт, ДатаДо, Организация, Склад,
        НоменклатураУслуги, НоменклатураТовары, СтавкаНДС)
        Рез = Новый Структура("Успех,Сообщение,ДокументСсылка", Ложь, "", Неопределено);
        Данные = ПолучитьДанныеИзВетаис(Хост, Порт, База, Пользователь, Пароль, ДатаОт, ДатаДо);
        Если Не Данные.Успех Тогда
                Рез.Сообщение = Данные.Ошибка; Возврат Рез;
        КонецЕсли;
        Если Данные.Итого = 0 Тогда
                Рез.Сообщение = "Нет данных за выбранный период"; Возврат Рез;
        КонецЕсли;
        ДатаОтФорм = Формат(ДатаОт, "ДФ=yyyy-MM-dd");
        ДатаДоФорм = Формат(КонецДня(ДатаДо), "ДФ=yyyy-MM-dd");
        Попытка
                Документ = Документы.ОтчетОРозничныхПродажах.СоздатьДокумент();
                Документ.Дата        = ДатаДо;
                Документ.Организация = Организация;
                Если ЗначениеЗаполнено(Склад) Тогда Документ.Склад = Склад; КонецЕсли;
                Документ.Комментарий = "Vetais: " + ДатаОтФорм + " — " + ДатаДоФорм + " | итого: " + Данные.Итого;
                Если ЗначениеЗаполнено(НоменклатураУслуги) И Данные.Услуги > 0 Тогда
                        Стр = Документ.Товары.Добавить();
                        Стр.Номенклатура = НоменклатураУслуги;
                        Стр.Количество = 1; Стр.Цена = Данные.Услуги; Стр.Сумма = Данные.Услуги;
                        Стр.СтавкаНДС = СтавкаНДС; Стр.СуммаНДС = 0;
                КонецЕсли;
                Если ЗначениеЗаполнено(НоменклатураТовары) И Данные.Товары > 0 Тогда
                        Стр = Документ.Товары.Добавить();
                        Стр.Номенклатура = НоменклатураТовары;
                        Стр.Количество = 1; Стр.Цена = Данные.Товары; Стр.Сумма = Данные.Товары;
                        Стр.СтавкаНДС = СтавкаНДС; Стр.СуммаНДС = 0;
                КонецЕсли;
                Документ.Записать(РежимЗаписиДокумента.Запись);
                Рез.Успех = Истина;
                Рез.ДокументСсылка = Документ.Ссылка;
                Рез.Сообщение =
                        "✅ Документ создан!" + Символы.ПС +
                        "Период: " + ДатаОтФорм + " — " + ДатаДоФорм + Символы.ПС +
                        "Итого:   " + Данные.Итого  + " руб." + Символы.ПС +
                        "Услуги:  " + Данные.Услуги + " руб." + Символы.ПС +
                        "Товары:  " + Данные.Товары + " руб." + Символы.ПС + Символы.ПС +
                        "Документ открыт для проверки. Проведите его вручную.";
        Исключение
                Рез.Сообщение =
                        "ОШИБКА СОЗДАНИЯ ДОКУМЕНТА В 1С:" + Символы.ПС + ОписаниеОшибки() + Символы.ПС + Символы.ПС +
                        "Возможные причины:" + Символы.ПС +
                        "- Нет табличной части 'Товары' в документе" + Символы.ПС +
                        "- Не заполнен обязательный реквизит (Склад, КассаККМ и др.)" + Символы.ПС +
                        "- Конфигурация не совпадает с БП 3.0";
        КонецПопытки;
        Возврат Рез;
КонецФункции

#КонецОбласти
